solution.solution.cpp:
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <vector>

class SharedList
{
public:
    static constexpr std::uint32_t MAGIC{ 0x5453494C };

    explicit SharedList(std::vector<std::byte>& block) : block{ block } {}

    void create()
    {
        put<std::uint32_t>(0, MAGIC);
        put<std::uint32_t>(4, 0);
        put<std::uint64_t>(8, 0);
        put<std::uint64_t>(16, 24);
    }

    bool valid() const { return block.size() >= 24 && get<std::uint32_t>(0) == MAGIC; }

    bool push(std::int32_t value)
    {
        if (!valid()) return false;
        const std::uint64_t at{ get<std::uint64_t>(16) };
        if (at + 16 > block.size()) return false;
        put<std::uint64_t>(at, 0);
        put<std::int32_t>(at + 8, value);
        put<std::uint32_t>(at + 12, 0);
        std::uint64_t link{ 8 };                                   // the field that must point at the new node
        for (std::uint64_t n{ get<std::uint64_t>(8) }; n != 0; n = get<std::uint64_t>(n)) link = n;
        put<std::uint64_t>(link, at);
        put<std::uint64_t>(16, at + 16);
        put<std::uint32_t>(4, get<std::uint32_t>(4) + 1);
        return true;
    }

    std::vector<std::int32_t> values() const
    {
        std::vector<std::int32_t> out;
        if (!valid()) return out;
        std::uint64_t n{ get<std::uint64_t>(8) };
        std::size_t guard{ 0 };
        while (n != 0 && n >= 24 && n + 16 <= block.size() && guard++ < block.size() / 16)
        {
            out.push_back(get<std::int32_t>(n + 8));
            n = get<std::uint64_t>(n);
        }
        return out;
    }

    std::uint32_t count() const { return valid() ? get<std::uint32_t>(4) : 0; }

private:
    std::vector<std::byte>& block;

    template <typename T> T get(std::uint64_t at) const { T v; std::memcpy(&v, block.data() + at, sizeof(T)); return v; }
    template <typename T> void put(std::uint64_t at, T v) { std::memcpy(block.data() + at, &v, sizeof(T)); }
};

unitTests:
using Block = std::vector<std::byte>;
TEST("creating and pushing") {
    Block block(256);
    SharedList list{ block };
    CHECK(!list.valid());
    list.create();
    CHECK(list.valid());
    CHECK(list.values().empty());
    CHECK(list.push(10)); CHECK(list.push(20)); CHECK(list.push(-5));
    CHECK_EQ(list.values(), (std::vector<std::int32_t>{ 10, 20, -5 }));
    CHECK_EQ(list.count(), 3u);
}
TEST("a copy at another address still works") {
    Block block(256);
    SharedList list{ block };
    list.create();
    for (int v : { 1, 2, 3, 4 }) list.push(v);
    Block elsewhere(block);
    SharedList view{ elsewhere };
    CHECK(view.valid());
    CHECK_EQ(view.values(), (std::vector<std::int32_t>{ 1, 2, 3, 4 }));
    view.push(5);
    CHECK_EQ(view.values().size(), 5u);
    CHECK_EQ(list.values().size(), 4u);
}
TEST("full blocks refuse") {
    Block block(24 + 16 * 2);
    SharedList list{ block };
    list.create();
    CHECK(list.push(1)); CHECK(list.push(2));
    CHECK(!list.push(3));
    CHECK_EQ(list.count(), 2u);
}
TEST("corrupt offsets cannot escape the block") {
    Block block(128);
    SharedList list{ block };
    list.create();
    list.push(7);
    list.push(8);
    const std::uint64_t bad{ 1000 };
    std::memcpy(block.data() + 24, &bad, 8);
    CHECK_EQ(list.values(), (std::vector<std::int32_t>{ 7 }));
    const std::uint64_t loop{ 24 };
    std::memcpy(block.data() + 24, &loop, 8);
    CHECK(list.values().size() <= 8u);
}

